 * @param requestId 全局唯一请求标识（幂等去重键）
 * @param reason    清除理由
 */
public record PurgeAttachmentRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 1024) String reason) {
}

