package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.Instant;

/**
 * 附件元数据响应。
 *
 * @param attachmentId   附件唯一标识
 * @param observationId  所属观测记录唯一标识
 * @param mediaType      附件媒体类型
 * @param purged         附件内容是否已被物理清除
 * @param createdAtUtc   登记完成时刻（UTC，ISO-8601）
 * @param purgedAtUtc    物理清除完成时刻（UTC）；未清除不返回
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record AttachmentResponse(
        String attachmentId,
        String observationId,
        String mediaType,
        boolean purged,
        Instant createdAtUtc,
        Instant purgedAtUtc) {

    public static AttachmentResponse of(AttachmentRecord record) {
        return new AttachmentResponse(record.attachmentId(), record.observationId(), record.mediaType(),
                record.purged(), record.createdAtUtc(), record.purgedAtUtc());
    }
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.Instant;

/**
 * 脱敏版本响应：明细与历史共用，字段、排序与 null 语义稳定。
 *
 * @param redactionId     脱敏版本全局唯一标识
 * @param observationId   所属观测记录唯一标识
 * @param attachmentId    被脱敏附件唯一标识
 * @param version         附件内递增脱敏版本号
 * @param ruleVersion     使用的规则版本
 * @param replacementNote 替换说明（脱敏后公开展示的受限摘要原文）
 * @param status          公开展示状态：ACTIVE / REVOKED
 * @param requestId       生成该版本的请求标识
 * @param createdAtUtc    生成时刻（UTC，ISO-8601）
 * @param revokedAtUtc    撤销公开展示资格时刻（UTC）；未撤销不返回
 * @param revokeReason    撤销理由；未撤销不返回
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record RedactionVersionResponse(
        String redactionId,
        String observationId,
        String attachmentId,
        int version,
        String ruleVersion,
        String replacementNote,
        String status,
        String requestId,
        Instant createdAtUtc,
        Instant revokedAtUtc,
        String revokeReason) {

    public static RedactionVersionResponse of(RedactionVersionRecord record) {
        return new RedactionVersionResponse(record.redactionId(), record.observationId(), record.attachmentId(),
                record.version(), record.ruleVersion(), record.replacementNote(),
                record.active() ? "ACTIVE" : "REVOKED", record.requestId(), record.createdAtUtc(),
                record.revokedAtUtc(), record.revokeReason());
    }
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 附件展示视图：公开查询只返回最新有效（ACTIVE）脱敏版本的替换说明；
 * 无有效脱敏版本时返回原始摘要（物理清除后 summary 为 null）。
 *
 * @param attachmentId     附件唯一标识
 * @param observationId    所属观测记录唯一标识
 * @param mediaType        附件媒体类型
 * @param purged           附件内容是否已被物理清除
 * @param displayType      展示类型：ORIGINAL 原始摘要 / REDACTION 脱敏版本
 * @param summary          展示摘要原文；物理清除后为 null
 * @param redactionId      展示来源脱敏版本标识；ORIGINAL 时不返回
 * @param redactionVersion 展示来源脱敏版本号；ORIGINAL 时不返回
 * @param ruleVersion      展示来源规则版本；ORIGINAL 时不返回
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record AttachmentViewResponse(
        String attachmentId,
        String observationId,
        String mediaType,
        boolean purged,
        String displayType,
        String summary,
        String redactionId,
        Integer redactionVersion,
        String ruleVersion) {

    /**
     * 原始摘要视图（公开无有效脱敏，或证据角色按版本 0 读取）。
     */
    public static AttachmentViewResponse original(AttachmentRecord attachment) {
        return new AttachmentViewResponse(attachment.attachmentId(), attachment.observationId(),
                attachment.mediaType(), attachment.purged(), "ORIGINAL",
                attachment.contentSummary(), null, null, null);
    }

    /**
     * 脱敏版本视图。
     */
    public static AttachmentViewResponse redacted(AttachmentRecord attachment, RedactionVersionRecord version) {
        return new AttachmentViewResponse(attachment.attachmentId(), attachment.observationId(),
                attachment.mediaType(), attachment.purged(), "REDACTION",
                version.replacementNote(), version.redactionId(), version.version(), version.ruleVersion());
    }
}

